"""
CI/CD snippet generators.

Produces GitHub Actions workflow YAML and Jenkins Declarative Pipeline
Groovy for running a JMeter test as part of a CI pipeline.
"""

from __future__ import annotations


def export_github_actions(
    test_name: str = "Performance Test",
    jmx_filename: str = "test.jmx",
    results_dir: str = "results",
    jmeter_version: str = "5.6.3",
    threads: int = 1,
    rampup: int = 1,
    loops: int = 1,
) -> str:
    """Return a GitHub Actions workflow YAML string."""
    return f"""\
# {test_name} — JMeter performance test
# Generated by ProjectStack
name: {test_name.replace(' ', '-')}

on:
  push:
    branches: [ main, master ]
  pull_request:
    branches: [ main, master ]
  workflow_dispatch:
    inputs:
      threads:
        description: 'Virtual users (threads)'
        default: '{threads}'
      loops:
        description: 'Loop count'
        default: '{loops}'

jobs:
  performance-test:
    runs-on: ubuntu-latest

    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Java
        uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: '17'

      - name: Download JMeter {jmeter_version}
        run: |
          wget -q https://downloads.apache.org/jmeter/binaries/apache-jmeter-{jmeter_version}.tgz
          tar -xzf apache-jmeter-{jmeter_version}.tgz
          echo "${{{{ github.workspace }}}}/apache-jmeter-{jmeter_version}/bin" >> $GITHUB_PATH

      - name: Run JMeter test
        run: |
          mkdir -p {results_dir}
          jmeter -n \\
            -t {jmx_filename} \\
            -l {results_dir}/results.jtl \\
            -e -o {results_dir}/html \\
            -Jthreads=${{{{ github.event.inputs.threads || '{threads}' }}}} \\
            -Jloops=${{{{ github.event.inputs.loops || '{loops}' }}}} \\
            -Jrampup={rampup}

      - name: Upload results
        uses: actions/upload-artifact@v4
        if: always()
        with:
          name: jmeter-results
          path: {results_dir}/

      - name: Check for errors
        run: |
          ERROR_COUNT=$(grep -c ",false," {results_dir}/results.jtl 2>/dev/null || echo 0)
          echo "Errors: $ERROR_COUNT"
          if [ "$ERROR_COUNT" -gt "0" ]; then
            echo "::warning::$ERROR_COUNT failed requests detected"
          fi
"""


def export_jenkins(
    test_name: str = "Performance Test",
    jmx_filename: str = "test.jmx",
    results_dir: str = "results",
    jmeter_version: str = "5.6.3",
    threads: int = 1,
    rampup: int = 1,
    loops: int = 1,
) -> str:
    """Return a Jenkins Declarative Pipeline Groovy string."""
    sh_block = (
        "sh '''\n"
        f"                    mkdir -p ${{{results_dir}}}\n"
        f"                    /opt/apache-jmeter-{jmeter_version}/bin/jmeter -n \\\n"
        f"                        -t {jmx_filename} \\\n"
        f"                        -l ${{{results_dir}}}/results.jtl \\\n"
        f"                        -e -o ${{{results_dir}}}/html \\\n"
        "                        -Jthreads=$THREADS \\\n"
        "                        -Jloops=$LOOPS \\\n"
        "                        -Jrampup=$RAMPUP\n"
        "                '''"
    )
    return (
        f"// {test_name} — JMeter performance test\n"
        "// Generated by ProjectStack\n"
        "pipeline {\n"
        "    agent any\n\n"
        "    parameters {\n"
        f"        string(name: 'THREADS', defaultValue: '{threads}', description: 'Virtual users')\n"
        f"        string(name: 'LOOPS',   defaultValue: '{loops}',   description: 'Loop count')\n"
        f"        string(name: 'RAMPUP',  defaultValue: '{rampup}',  description: 'Ramp-up (seconds)')\n"
        "    }\n\n"
        "    stages {\n"
        "        stage('Checkout') {\n"
        "            steps {\n"
        "                checkout scm\n"
        "            }\n"
        "        }\n\n"
        "        stage('Run JMeter Test') {\n"
        "            steps {\n"
        f"                {sh_block}\n"
        "            }\n"
        "        }\n\n"
        "        stage('Publish Results') {\n"
        "            steps {\n"
        f"                perfReport sourceDataFiles: '{results_dir}/results.jtl'\n"
        "                publishHTML([\n"
        f"                    reportDir:   '{results_dir}/html',\n"
        "                    reportFiles: 'index.html',\n"
        "                    reportName:  'JMeter Report'\n"
        "                ])\n"
        "            }\n"
        "        }\n"
        "    }\n\n"
        "    post {\n"
        "        always {\n"
        f"            archiveArtifacts artifacts: '{results_dir}/**', fingerprint: true\n"
        "        }\n"
        "        failure {\n"
        f"            echo 'Performance test FAILED'\n"
        "        }\n"
        "    }\n"
        "}\n"
    )
